import React, { useEffect, useState } from 'react';
import { useParams } from 'react-router-dom';
import stallService from '../services/stallService';
import StallCard from '../components/StallCard';
import { isValidText, isValidPositiveNumber } from '../utils/helpers';
import '../styles/Pages.css';
import { toast } from 'react-toastify';

const StallAllocation = () => {
  const { eventId } = useParams();
  const [stalls, setStalls] = useState([]);
  const [loading, setLoading] = useState(false);
  const [showRequestForm, setShowRequestForm] = useState(false);
  const [requestData, setRequestData] = useState({
    stallName: '',
    category: '',
    size: '',
    price: '',
  });
  const [errors, setErrors] = useState({});

  useEffect(() => {
    fetchStalls();
  }, [eventId]);

  const fetchStalls = async () => {
    setLoading(true);
    try {
      const data = await stallService.getStallsByEvent(eventId);
      setStalls(data);
    } catch (error) {
      toast.error('Failed to fetch stalls');
    } finally {
      setLoading(false);
    }
  };

  const handleRequestStall = async (e) => {
    e.preventDefault();

    // Validate form
    const newErrors = validateStallForm();
    if (Object.keys(newErrors).length > 0) {
      setErrors(newErrors);
      toast.error('Please fill in all required fields correctly');
      return;
    }

    try {
      await stallService.requestStall({
        ...requestData,
        event: eventId,
      });
      toast.success('Stall request submitted!');
      setShowRequestForm(false);
      setRequestData({ stallName: '', category: '', size: '', price: '' });
      setErrors({});
      fetchStalls();
    } catch (error) {
      toast.error('Failed to request stall');
    }
  };

  const validateStallForm = () => {
    const newErrors = {};

    // Stall name validation
    if (!requestData.stallName.trim()) {
      newErrors.stallName = 'Stall name is required';
    } else if (!isValidText(requestData.stallName, 3)) {
      newErrors.stallName = 'Stall name must be at least 3 characters';
    }

    // Category validation
    if (!requestData.category) {
      newErrors.category = 'Category is required';
    }

    // Size validation
    if (!requestData.size) {
      newErrors.size = 'Size is required';
    }

    // Price validation
    if (!requestData.price) {
      newErrors.price = 'Price is required';
    } else if (!isValidPositiveNumber(requestData.price)) {
      newErrors.price = 'Price must be a positive number';
    }

    return newErrors;
  };

  const handleInputChange = (e) => {
    const { name, value } = e.target;
    setRequestData(prev => ({
      ...prev,
      [name]: value,
    }));
    // Clear field error when user starts typing
    if (errors[name]) {
      setErrors(prev => ({
        ...prev,
        [name]: '',
      }));
    }
  };

  return (
    <div className="stall-allocation-page">
      <div className="page-header">
        <h1>Stall Allocation</h1>
        <p>Request stalls for the event</p>
      </div>

      <div className="stall-content">
        <div className="stall-section">
          {loading ? (
            <div className="loading">Loading stalls...</div>
          ) : (
            <div className="stalls-grid">
              {stalls.map(stall => (
                <StallCard
                  key={stall._id}
                  stall={stall}
                  onBook={() => {}}
                  onViewDetails={() => {}}
                />
              ))}
            </div>
          )}
        </div>

        <div className="request-section">
          <button 
            className="btn-primary"
            onClick={() => setShowRequestForm(!showRequestForm)}
          >
            {showRequestForm ? 'Cancel' : 'Request New Stall'}
          </button>

          {showRequestForm && (
            <form className="stall-request-form" onSubmit={handleRequestStall}>
              <div className="form-group">
                <label htmlFor="stallName">Stall Name</label>
                <input
                  type="text"
                  id="stallName"
                  name="stallName"
                  value={requestData.stallName}
                  onChange={handleInputChange}
                  required
                  placeholder="Enter stall name"
                />
              </div>

              <div className="form-group">
                <label htmlFor="category">Category</label>
                <select
                  id="category"
                  name="category"
                  value={requestData.category}
                  onChange={handleInputChange}
                  required
                >
                  <option value="">Select category</option>
                  <option value="food">Food</option>
                  <option value="crafts">Crafts</option>
                  <option value="retail">Retail</option>
                  <option value="other">Other</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="size">Size</label>
                <select
                  id="size"
                  name="size"
                  value={requestData.size}
                  onChange={handleInputChange}
                  required
                >
                  <option value="">Select size</option>
                  <option value="small">Small (10x10)</option>
                  <option value="medium">Medium (15x15)</option>
                  <option value="large">Large (20x20)</option>
                </select>
              </div>

              <div className="form-group">
                <label htmlFor="price">Price (per day)</label>
                <input
                  type="number"
                  id="price"
                  name="price"
                  value={requestData.price}
                  onChange={handleInputChange}
                  required
                  placeholder="Enter price"
                  min="0"
                />
              </div>

              <button type="submit" className="btn-success">
                Submit Request
              </button>
            </form>
          )}
        </div>
      </div>
    </div>
  );
};

export default StallAllocation;
